import numpy as np
import scipy.linalg
from typing import Any


def _principal_sqrt_eig(A):
    """
    Compute principal matrix square root via eigenvalue decomposition.

    For A = V @ diag(eigenvalues) @ V^{-1},
    sqrt(A) = V @ diag(sqrt(eigenvalues)) @ V^{-1}

    The principal square root uses the branch of sqrt with non-negative real part.

    Returns the result or None if the method fails.
    """
    n = A.shape[0]

    # Eigenvalue decomposition
    try:
        eigenvalues, eigenvectors = np.linalg.eig(A)
    except np.linalg.LinAlgError:
        return None

    # Check if eigenvector matrix is well-conditioned
    cond = np.linalg.cond(eigenvectors)
    if cond > 1e12:
        return None

    # Compute principal square roots of eigenvalues
    # Principal sqrt has non-negative real part
    sqrt_eigenvalues = np.sqrt(eigenvalues)

    # Reconstruct: X = V @ diag(sqrt(eigenvalues)) @ V^{-1}
    try:
        V_inv = np.linalg.inv(eigenvectors)
    except np.linalg.LinAlgError:
        return None

    X = eigenvectors @ np.diag(sqrt_eigenvalues) @ V_inv

    return X


def _triangular_sqrt_schur(T):
    """
    Compute the square root of an upper triangular matrix T.
    Uses the recursive formula for triangular matrix square roots.
    """
    n = T.shape[0]
    S = np.zeros_like(T)

    # Diagonal elements: S[i,i] = sqrt(T[i,i]) with non-negative real part
    for i in range(n):
        S[i, i] = np.sqrt(T[i, i])

    # Off-diagonal elements using the formula:
    # S[i,j] = (T[i,j] - sum(S[i,k]*S[k,j] for k in (i+1..j-1))) / (S[i,i] + S[j,j])
    for j in range(1, n):
        for i in range(j - 1, -1, -1):
            s = T[i, j]
            for k in range(i + 1, j):
                s -= S[i, k] * S[k, j]
            denom = S[i, i] + S[j, j]
            if abs(denom) < 1e-15:
                # Handle near-zero denominator
                S[i, j] = 0.0
            else:
                S[i, j] = s / denom

    return S


def _principal_sqrt_schur(A):
    """
    Compute principal matrix square root via Schur decomposition.
    A = Q @ T @ Q^H (Schur decomposition)
    sqrt(A) = Q @ sqrt(T) @ Q^H
    """
    n = A.shape[0]

    # Schur decomposition
    T, Q = scipy.linalg.schur(A, output='complex')

    # Compute sqrt of upper triangular T
    S = _triangular_sqrt_schur(T)

    # Transform back
    X = Q @ S @ Q.conj().T

    return X


def _verify_solution(X, A, rtol=1e-5, atol=1e-8):
    """
    Verify that X @ X ≈ A within tolerance.
    """
    if X is None:
        return False
    if not np.all(np.isfinite(X)):
        return False
    residual = X @ X - A
    return np.allclose(residual, 0, rtol=rtol, atol=atol)


class Solver:
    def solve(self, problem, **kwargs) -> Any:
        """
        Solves the matrix square root problem.

        Computes the principal matrix square root X such that X @ X = A.
        Uses eigenvalue decomposition as fast path, falls back to Schur method.

        :param problem: A dictionary with key "matrix" containing the input matrix.
        :return: A dictionary with key "sqrtm" containing "X" - the principal square root.
        """
        A_raw = problem["matrix"]

        # Convert input to numpy array of complex numbers
        A = np.array(A_raw, dtype=complex)
        n = A.shape[0]

        # Handle trivial cases
        if n == 0:
            return {"sqrtm": {"X": []}}

        if n == 1:
            val = np.sqrt(A[0, 0])
            return {"sqrtm": {"X": [[val]]}}

        X = None

        # Try eigenvalue decomposition first (fastest for well-conditioned diagonalizable matrices)
        X_eig = _principal_sqrt_eig(A)
        if _verify_solution(X_eig, A):
            X = X_eig

        # If eig failed, try Schur-based approach with our own triangular sqrt
        if X is None:
            try:
                X_schur = _principal_sqrt_schur(A)
                if _verify_solution(X_schur, A):
                    X = X_schur
            except Exception:
                pass

        # Final fallback: scipy.linalg.sqrtm
        if X is None:
            try:
                X_scipy, _ = scipy.linalg.sqrtm(A, disp=False)
                if _verify_solution(X_scipy, A):
                    X = X_scipy
            except Exception:
                pass

        # If everything failed, return empty
        if X is None:
            return {"sqrtm": {"X": []}}

        # Convert to list of lists for serialization
        return {"sqrtm": {"X": X.tolist()}}
