import numpy as np
import scipy.linalg
from typing import Any


def _sqrtm_eig(A):
    """
    Compute principal matrix square root via eigenvalue decomposition.
    A = V @ diag(eigs) @ V^{-1}
    sqrt(A) = V @ diag(sqrt(eigs)) @ V^{-1}
    """
    # Use scipy.linalg.eig which can be faster
    eigenvalues, eigenvectors = scipy.linalg.eig(A, overwrite_a=False)

    # Principal sqrt: non-negative real part (np.sqrt already does this)
    sqrt_eigs = np.sqrt(eigenvalues)

    # Use solve instead of explicit inverse for better accuracy/speed
    # X = V @ diag(sqrt_eigs) @ V^{-1}
    # X @ V = V @ diag(sqrt_eigs)
    # So X = (V @ diag(sqrt_eigs)) @ V^{-1}
    # Or: solve(V.T, (V @ diag(sqrt_eigs)).T).T
    X = eigenvectors @ (sqrt_eigs[:, None] * scipy.linalg.inv(eigenvectors, overwrite_a=False))

    return X


def _sqrtm_schur_triangular(A):
    """
    Compute principal matrix square root via Schur decomposition
    with direct triangular square root computation.
    """
    # Complex Schur decomposition
    T, Q = scipy.linalg.schur(A, output='complex')
    n = T.shape[0]

    # Compute sqrt of upper triangular T using Bjorck-Hammarling
    S = np.zeros((n, n), dtype=T.dtype)

    # Diagonal
    for i in range(n):
        S[i, i] = np.sqrt(T[i, i])

    # Off-diagonal: column by column
    for j in range(1, n):
        for i in range(j - 1, -1, -1):
            # Sum S[i,k]*S[k,j] for k in (i+1..j-1)
            if j > i + 1:
                s = T[i, j] - np.dot(S[i, i+1:j], S[i+1:j, j])
            else:
                s = T[i, j]
            denom = S[i, i] + S[j, j]
            if abs(denom) > 1e-15:
                S[i, j] = s / denom
            else:
                S[i, j] = 0.0

    # Transform back: X = Q @ S @ Q^H
    X = Q @ (S @ Q.conj().T)
    return X


class Solver:
    def solve(self, problem, **kwargs) -> Any:
        """
        Solves the matrix square root problem.
        Computes the principal matrix square root X such that X @ X = A.
        """
        A_raw = problem["matrix"]
        A = np.array(A_raw, dtype=complex)
        n = A.shape[0]

        if n == 0:
            return {"sqrtm": {"X": []}}

        if n == 1:
            val = np.sqrt(A[0, 0])
            return {"sqrtm": {"X": [[complex(val)]]}}

        X = None

        # Strategy 1: Eigenvalue decomposition (fast for diagonalizable matrices)
        try:
            X = _sqrtm_eig(A)
        except Exception:
            X = None

        # Quick cheap check: just verify a few elements of X @ X vs A
        if X is not None and np.all(np.isfinite(X)):
            # Cheap check: diagonal of X@X should match diagonal of A
            diag_check = np.einsum('ij,ji->i', X, X)
            if np.allclose(diag_check, np.diag(A), rtol=1e-4, atol=1e-7):
                # More thorough but still partial check
                # Check first column of X@X
                col0_check = X @ X[:, 0]
                if np.allclose(col0_check, A[:, 0], rtol=1e-4, atol=1e-7):
                    # Looks good, do full verification
                    if np.allclose(X @ X, A, rtol=1e-5, atol=1e-8):
                        return {"sqrtm": {"X": X.tolist()}}

        # Strategy 2: Schur-based approach
        try:
            X = _sqrtm_schur_triangular(A)
            if X is not None and np.all(np.isfinite(X)):
                if np.allclose(X @ X, A, rtol=1e-5, atol=1e-8):
                    return {"sqrtm": {"X": X.tolist()}}
        except Exception:
            pass

        # Strategy 3: scipy fallback
        try:
            X, _ = scipy.linalg.sqrtm(A, disp=False)
            if X is not None and np.all(np.isfinite(X)):
                return {"sqrtm": {"X": X.tolist()}}
        except Exception:
            pass

        return {"sqrtm": {"X": []}}
